package com.projecteden.ranking.controller;import java.util.List;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import com.projecteden.ranking.dto.RankingResponseDTO;import com.projecteden.ranking.service.RankingService;import com.projecteden.user.domain.User;@RestController@RequestMapping("/api/ranking")public class RankingController{private final RankingService service;public RankingController(RankingService service){this.service=service;}@GetMapping("/friends")public List<RankingResponseDTO> ranking(@AuthenticationPrincipal User u){return service.getFriendRanking(u.getId());}}
